DIALOGS = [
[trp_sod_strategy_advisor, "sa_select_ranged_infantry", [
		(try_begin),
			(eq, "$g_sod_sa_talk_subject", 11),
			(str_store_string, s1, "@The crossbows of the Swadians are not as skilled as the Rhodoks but that does not make them any less lethal.  They range in skill from Skirmisher, Crossbowman, to Sharpshooter."),
		(else_try),
			(eq, "$g_sod_sa_talk_subject", 12),
			(str_store_string, s1, "@The skill of the Vaegir archers is outmatched by any army in Calradia.  As a matter of fact, the bows of the Vaegirs remind me of the Villianese."),
		(else_try),
			(eq, "$g_sod_sa_talk_subject", 13),
			(str_store_string, s1, "@The Khergits do not fight on foot unless you siege their homeland.  Of course if they could fight on horseback during a siege, I am sure they would.  Every unit has the possibility of throwing or shooting something at you."),
		(else_try),
			(eq, "$g_sod_sa_talk_subject", 14),
			(str_store_string, s1, "@The Nords depend slightly on archers ranging in skill from Huntsman, Archer, to Veteran Archer.  The Nords are not known for their bow making abilities, but beware of ambushes and always think ahead.  "),
		(else_try),
			(eq, "$g_sod_sa_talk_subject", 15),
			(str_store_string, s1, "@Crossbowmen are easy to train and the Rhodoks have mastered the art.  Their troops range in skill from Crossbowmen, Trained Crossbowmen, Veteran Crossbowmen, to Sharpshooter.  This is one army I would prefer to fight in the open opposed to the close confines of a castle.  "),
		(else_try),
			(eq, "$g_sod_sa_talk_subject", 21),
			(str_store_string, s1, "@Antarians ranged infantry consists of Javelin men and Trained Javelin men.  Nothing extraordinary but their javelin throwers are famous for breaking through shield walls softening up the defenses for the shock infantry.  In addition, they are a proficient light infantry force and excel in melee combat when compared to most archer class troops their rank.  This is due to the fact they undergo all of the basic training the infantry receives.   "),
		(else_try),
			(eq, "$g_sod_sa_talk_subject", 22),
			(str_store_string, s1, "@The Marinarians ranged infantry focuses on crossbowmen and increases in rank from Crossbowman, Trained Crossbowmen, Elite Crossbowmen, to Sharpshooter.  The Marinian Sharpshooter is deadly at range and their large shields make them deadly at melee as well."),
		(else_try),
			(eq, "$g_sod_sa_talk_subject", 23),
			(str_store_string, s1, "@Even more surprising than seeing an Adenian infantry soldier is seeing an Adenian bowman.  Typically only employed as guardians of castles, they have been instrumental in a few well known battles when heavy cavalry cannot reach the enemy.  Their structure consists of Archers, Veteran Archers, and Elite Archers."),
		(else_try),
			(eq, "$g_sod_sa_talk_subject", 24),
			(str_store_string, s1, "@The ranged infantry of the Villianese is their trademark.  Their bowmen undergo a strict training regimen beginning as children.  Their marksmen are deadly before you can pinpoint their location.  Their ranks include in order of importance include Longbowman, Veteran Longbowman, Elite Longowman, and Sharpshooter.  The only effective strategy against them is a cavalry charge where you can afford a few losses.  "),
		(else_try),
			(eq, "$g_sod_sa_talk_subject", 37),
			(str_store_string, s1, "@The Boar Clan does not have any ranged infantry units unless you count the occasional javelin thrown from a Clansman.  All of their ranged force is mounted, which is also limited in numbers.  Use this knowledge to your advantage should you ever find yourself on the wrong side of a Boar Clan hammer."),
		(else_try),
			(eq, "$g_sod_sa_talk_subject", 25),
			(str_store_string, s1, "@The Zerrikanian ranged infantry consists in order of importance of short bowmen and Dvor archers.  While they are not exceptional when compared to other armies archers, they have a remarkable way of appearing when you least expect them being athletic and lightly armored.  The Dvor archers are often employed as body guards to rich nobles."),
		(try_end),
	], "{s1}", "sa_select_3", []],
]
